  const results:Array<{source:"internal";item:Internal}|{source:"external";item:External}>=[...internal.map(item=>({source:"internal" as const,item})),...external.filter(item=>!internal.some(existing=>norm(existing.title)===norm(item.title))).map(item=>({source:"external" as const,item}))];
