  const adminActivityNeedle=norm(adminActivityQuery);
  const filteredAdminActivityOptions=adminActivityOptions.filter(option=>!adminActivityNeedle||norm(`${option.name} ${activityCategoryLabel(option.category_name||"")}`).includes(adminActivityNeedle));
  const matchedAdminCategoryIds=new Set(filteredAdminActivityOptions.map(option=>option.category_id).filter(Boolean));
  const filteredAdminActivityCategories=adminActivityCategories.filter(category=>!adminActivityNeedle||norm(activityCategoryLabel(category.name)).includes(adminActivityNeedle)||matchedAdminCategoryIds.has(category.id));
  const travelActivityCategoryId=adminActivityCategories.find(category=>category.name==="Travel Activity")?.id||"";
  const adminBaseKind=contentTypes.find(type=>type.id===adminKind)?.base_kind||adminKind;
  const effectiveAdminActivityCount=adminActivityOptions.filter(option=>adminActivityIds.includes(option.id)||Boolean(option.category_id&&adminActivityCategoryIds.includes(option.category_id))).length;
  const sortOptions:Array<{id:Sort;label:string}>=[...((effectiveKind==="movie"||effectiveKind==="series")?[{id:"imdbTop100" as const,label:"IMDb Top 100 · 1’den 100’e"},{id:"imdbTop250" as const,label:"IMDb Top 250 · 1’den 250’ye"}]:[]),{id:"wanting",label:`${words?.wanting||"İsteyenler"} · çoktan aza`},{id:"done",label:`${words?.doers||"Deneyimleyenler"} · çoktan aza`},{id:"active",label:"Aktif etkinlikler · çoktan aza"},{id:"alphabetical",label:"Alfabetik · A’dan Z’ye"}];
