        <div className="mt-3 grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-4">{orderedKinds.map(item=>{const count=kindCounts.get(item.id)??0;const itemBaseKind=contentTypes.find(type=>type.id===item.id)?.base_kind||item.id;const intent=cardWords(itemBaseKind,contentTypes.find(type=>type.id===item.id)?.ui_labels).want;return <button key={item.id} type="button" onClick={()=>chooseCategory(item.id)} className="group min-h-[126px] rounded-2xl border border-slate-200 bg-white p-4 text-left transition hover:-translate-y-0.5 hover:border-emerald-300 hover:shadow-md"><span className="flex items-start justify-between gap-2"><span className="text-2xl">{item.icon}</span><span className="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-black text-emerald-800">{count}</span></span><span className="mt-3 block font-black text-slate-950 group-hover:text-emerald-800">{item.label}</span><span className="mt-1 block text-xs font-semibold text-slate-500">{intent}</span></button>})}</div>
