      {effectiveKind==="place"&&<PlaceHierarchyBrowser onData={(cards,nodes,selection)=>{setPlaceLoading(false);setActivePlaceDistrictId(selection.districtTargetId);setPlaceBrowseRootId(selection.districtTargetId||selection.cityTargetId||"");setPlaceBrowseIds(new Set(cards.map(card=>card.canonical_target_id)));setCatalogue(current=>{const incoming=cards as Catalogue[];const existing=new Map(current.map(card=>[card.canonical_target_id,card]));const ids=new Set(incoming.map(card=>card.canonical_target_id));return [...incoming.map(card=>{const previous=existing.get(card.canonical_target_id);return {...previous,...card,own_common_intent_id:previous?.own_common_intent_id??card.own_common_intent_id}}),...current.filter(card=>!ids.has(card.canonical_target_id))]});setPlaceList(nodes.map((node:PlaceBrowseNode)=>({id:node.target_id,catalogItemId:"",title:node.title,coverUrl:null,wikiId:node.source_key,kind:node.scope==="city"?"Şehir":node.scope==="district"?"İlçe":node.scope,countryId:"country:TR",country:"Türkiye",cityId:node.parent_target_id||node.target_id,city:node.scope==="city"?node.title:"",district:node.scope==="district"?node.title:"",parentTargetId:node.parent_target_id||"",sourceUrl:"",mapUrl:""})))}}/>}
