      {previewArtist&&<div className="mt-4"><SpotifyArtistPanel artistId={previewArtist.externalId} headerAction={<><button type="button" disabled={busy} onClick={()=>void addExternal(previewArtist)} className="rounded-xl bg-emerald-600 px-5 py-3 text-sm font-black text-white shadow-sm hover:bg-emerald-700 disabled:opacity-50">＋ Sanatçıyı kütüphaneye ekle</button><button type="button" onClick={()=>setPreviewArtist(null)} className="text-sm font-semibold text-slate-500">Kapat</button></>}/></div>}
      {manual&&<form onSubmit={event=>{event.preventDefault();void addManual(event.currentTarget)}} className="mt-5 grid gap-4 rounded-2xl border border-emerald-100 bg-emerald-50/40 p-5 md:grid-cols-2"><div className="md:col-span-2"><h3 className="text-lg font-black">{manualIsClub?"Yeni spor kulübü ekle":"Kütüphaneye yeni kayıt ekle"}</h3><p className="mt-1 text-sm text-slate-500">{adminDirectManual?"Kart doğrudan seçtiğin türde ve Tümü listesinde yayınlanacak.":"Kaydın UIN yönetimine iletilecek; kontrol sonucu bildirimle paylaşılacak."}</p></div><label className="text-sm font-bold">İçerik türü *<select name="contentTypeId" required value={manualType} onChange={event=>setManualType(event.target.value)} className="mt-1 w-full rounded-xl border bg-white px-4 py-3"><option value="">Tür seç</option>{contentTypes.filter(type=>type.active&&(adminDirectManual||type.base_kind==="club"||type.ui_labels?.search_provider==="manual"||type.ui_labels?.manual_fallback==="true")).map(type=><option key={type.id} value={type.id}>{type.icon} {type.label}</option>)}</select></label><label className="text-sm font-bold">{manualIsClub?"Kulübün tam adı *":"Kart adı *"}<input name="title" required maxLength={240} defaultValue={query} placeholder="Örn. Galatasaray" className="mt-1 w-full rounded-xl border px-4 py-3"/></label><label className="text-sm font-bold">{manualIsClub?"Kulübün kısa adı":"Yazar / sanatçı / alt bilgi"}<input name="creatorName" maxLength={240} className="mt-1 w-full rounded-xl border px-4 py-3"/></label>{!manualIsClub&&<label className="text-sm font-bold">Kapak fotoğrafı bağlantısı<input name="coverUrl" type="url" placeholder="https://…" className="mt-1 w-full rounded-xl border px-4 py-3"/></label>}<label className="text-sm font-bold md:col-span-2">Açıklama<textarea name="description" maxLength={1000} placeholder="Kısaca açıkla" className="mt-1 w-full rounded-xl border px-4 py-3"/></label><label className="text-sm font-bold md:col-span-2">Kaynak bağlantısı{!adminDirectManual&&!manualIsClub?" *":""}<input name="referenceUrl" type="url" required={!adminDirectManual&&!manualIsClub} placeholder={adminDirectManual||manualIsClub?"Varsa kaynak bağlantısı":"İçeriği doğrulayabileceğimiz bağlantı"} className="mt-1 w-full rounded-xl border px-4 py-3"/></label>{adminDirectManual&&manualIsClub&&<div className="md:col-span-2"><ClubProfileEditor value={manualClub} onChange={setManualClub}/></div>}{message&&<p role="alert" className="rounded-xl bg-red-50 p-3 text-sm font-bold text-red-700 md:col-span-2">{message}</p>}<div className="flex gap-3 md:col-span-2"><button disabled={busy||!manualType} className="flex-1 rounded-xl bg-emerald-600 px-5 py-3 font-black text-white disabled:opacity-50">{busy?"Kaydediliyor…":adminDirectManual?(manualIsClub?"Kulübü oluştur":"Kartı doğrudan ekle"):"UIN yönetimine gönder"}</button><button type="button" onClick={()=>setManual(false)} className="rounded-xl border bg-white px-4 py-3 font-bold">Vazgeç</button></div></form>}
